export class OrderRepository {
  findByUser(userId) {
    return new Promise((resolve, reject) => {
      query('orders', (o) => o.user_id === userId && o.deleted_at === null,
        (err, rows) => (err ? reject(err) : resolve(rows)));
    });
  }

  findPaid() {
    return new Promise((resolve, reject) => {
      query('orders', (o) => o.status === 'paid' && o.deleted_at === null,
        (err, rows) => (err ? reject(err) : resolve(rows)));
    });
  }

  findPaymentsForOrder(orderId) {
    return new Promise((resolve, reject) => {
      query('payments', (p) => p.order_id === orderId, (err, rows) =>
        err ? reject(err) : resolve(rows));
    });
  }

  findUncapturedPayments() {
    return new Promise((resolve, reject) => {
      query('payments', (p) => p.captured === false, (err, rows) =>
        err ? reject(err) : resolve(rows));
    });
  }
}
import { UserRepository } from '../repositories/user-repository.js';

const users = new UserRepository();

export function listActiveUsers(callback) {
  users.findActive().then((rows) => callback(null, rows), callback);
}

export function findUser(id, callback) {
  users.findById(id).then((user) => callback(null, user), callback);
}

export function softDeleteUser(id, when, callback) {
  users.softDelete(id, when).then((user) => callback(null, user), callback);
}
